/**
 * Calendar's wire shapes, generated by Google from the API's Discovery
 * document (@googleapis/calendar) rather than written here. Type-only: nothing
 * of that package runs. Every field is optional and may be null, because that
 * is what the schema promises. The one import in domain/, on purpose.
 */
import type { DeepReadonly } from "@foreverworks/mcp-kit";
import type { calendar_v3 } from "@googleapis/calendar";

export type RawEvent = DeepReadonly<calendar_v3.Schema$Event>;
export type RawWhen = DeepReadonly<calendar_v3.Schema$EventDateTime>;
export type RawAttendee = DeepReadonly<calendar_v3.Schema$EventAttendee>;
export type RawCalendar = DeepReadonly<calendar_v3.Schema$CalendarListEntry>;

/** freebusy.query, used only for OTHER people's availability (see domain/busy.ts for why). */
export type RawFreeBusyRequest = DeepReadonly<calendar_v3.Schema$FreeBusyRequest>;
export type RawFreeBusyResponse = DeepReadonly<calendar_v3.Schema$FreeBusyResponse>;
export type RawFreeBusyCalendar = DeepReadonly<calendar_v3.Schema$FreeBusyCalendar>;
export type RawTimePeriod = DeepReadonly<calendar_v3.Schema$TimePeriod>;
export type RawFreeBusyError = DeepReadonly<calendar_v3.Schema$Error>;
